"""Conformance arm 3 — multiprocessing spawn works from the mounted image.

The interpreter re-exec edge: a spawn-context Pool(2) must RETURN, never
hang. The child process re-execs sys.executable; under tebako that is the
runtime's own exe (with the driver-armed env inherited), and the preload
shim serves its VFS reads — exactly the boot the fs TU composes for its
own re-exec. A wedge here is the classic failure; the caller
(tools/conformance) enforces a hard deadline and kills the tree on
expiry, so a hang fails the arm by name instead of wedging CI.
"""

import multiprocessing as mp
import os
import sys

_site = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
if _site not in sys.path:
    sys.path.insert(0, _site)


def square(item):
    # The worker proves the child interpreter runs AND sees the payload:
    # it imports the toolkit package (mounted site-packages) in the child.
    import pydata_toolkit

    return item * item, pydata_toolkit.__version__, os.getpid()


def main():
    print("sys.executable: %s" % sys.executable)
    print("start method: spawn (explicit — the windows/macos default, the "
          "interpreter re-exec edge)")
    ctx = mp.get_context("spawn")
    with ctx.Pool(processes=2) as pool:
        results = pool.map(square, range(8))
    squares = [r[0] for r in results]
    want = [n * n for n in range(8)]
    if squares != want:
        sys.stderr.write("arm3: pool returned %s, want %s\n" % (squares, want))
        return 1
    child_pids = sorted({r[2] for r in results})
    print("pool(2).map over 8 items returned: %s" % squares)
    print("worker pids: %s (parent %d) — toolkit version from the child: %s"
          % (child_pids, os.getpid(), results[0][1]))
    if not child_pids or os.getpid() in child_pids:
        sys.stderr.write("arm3: the workers ran in the parent process — not a spawn\n")
        return 1
    print("ARM3-OK")
    return 0


if __name__ == "__main__":
    sys.exit(main())
